#include <stdio.h>
#include <string.h>

#define MAXP 64

/* BF：主串指针 i 每趟失配后回溯到 i-j+2 */
int Index_BF(const char *s, const char *t, int pos, int *cmpCount) {
    int i = pos, j = 1;
    int slen = (int)strlen(s), tlen = (int)strlen(t);
    *cmpCount = 0;
    while (i <= slen && j <= tlen) {
        ++(*cmpCount);
        if (s[i-1] == t[j-1]) { ++i; ++j; }
        else { i = i - j + 2; j = 1; }
    }
    return (j > tlen) ? i - tlen : 0;
}

/* 求 next 数组（位序 1-based，p[k-1] 表示第 k 个字符） */
void get_next(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) { ++i; ++j; next[i] = j; }
        else { j = next[j]; }
    }
}

/* KMP：主串指针 i 不回溯，只让 j 滑到 next[j] */
int Index_KMP(const char *s, const char *t, int pos, const int next[], int *cmpCount) {
    int i = pos, j = 1;
    int slen = (int)strlen(s), tlen = (int)strlen(t);
    *cmpCount = 0;
    while (i <= slen && j <= tlen) {
        ++(*cmpCount);
        if (j == 0 || s[i-1] == t[j-1]) { ++i; ++j; }
        else { j = next[j]; }
    }
    return (j > tlen) ? i - tlen : 0;
}

int main(void) {
    const char *cases[2][2];
    int next[MAXP], c1, c2, p1, p2, i;

    cases[0][0] = "ababcabcacbab"; cases[0][1] = "abcac";
    cases[1][0] = "aaaaab";        cases[1][1] = "aab";

    for (i = 0; i < 2; i++) {
        get_next(cases[i][1], next);
        p1 = Index_BF(cases[i][0], cases[i][1], 1, &c1);
        p2 = Index_KMP(cases[i][0], cases[i][1], 1, next, &c2);
        printf("主串 \"%s\"，模式串 \"%s\"\n", cases[i][0], cases[i][1]);
        printf("  BF  ：首次出现位置 = %d，字符比较 %d 次\n", p1, c1);
        printf("  KMP ：首次出现位置 = %d，字符比较 %d 次\n\n", p2, c2);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXP 64

void get_next(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) { ++i; ++j; next[i] = j; }
        else { j = next[j]; }
    }
}

/* 改进的 nextval：p[j] == p[next[j]] 时继续回退 */
void get_nextval(const char *p, int next[]) {
    int n = (int)strlen(p);
    int i = 1, j = 0;
    next[1] = 0;
    while (i < n) {
        if (j == 0 || p[i-1] == p[j-1]) {
            ++i; ++j;
            if (p[i-1] != p[j-1]) { next[i] = j; }
            else { next[i] = next[j]; }
        } else { j = next[j]; }
    }
}

int main(void) {
    const char *pats[3];
    int next[MAXP], nv[MAXP], i, k;

    pats[0] = "abcac"; pats[1] = "aaaab"; pats[2] = "aab";

    for (i = 0; i < 3; i++) {
        int len = (int)strlen(pats[i]);
        get_next(pats[i], next);
        get_nextval(pats[i], nv);
        printf("模式串 \"%s\" (m=%d)\n", pats[i], len);
        printf("  j      :");
        for (k = 1; k <= len; k++) printf("%4d", k);
        printf("\n  next   :");
        for (k = 1; k <= len; k++) printf("%4d", next[k]);
        printf("\n  nextval:");
        for (k = 1; k <= len; k++) printf("%4d", nv[k]);
        printf("\n\n");
    }
    return 0;
}

#include <stdio.h>

#define M 3
#define N 4

int main(void) {
    int a[M][N];
    int i, j;

    printf("二维数组 a[%d][%d]，C 语言行优先存放：\n", M, N);
    for (i = 0; i < M; i++)
        for (j = 0; j < N; j++)
            a[i][j] = i * N + j;              /* 行优先的线性下标 */
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) printf("%4d", a[i][j]);
        printf("\n");
    }

    printf("\n%-8s%-12s%-12s\n", "(i,j)", "row-major", "col-major");
    for (i = 0; i < M; i++)
        for (j = 0; j < N; j++)
            printf("(%d,%d)%4d%12d\n", i, j, i * N + j, j * M + i);

    /* 指针算术实测，验证 LOC(i,j) = base + (i*n+j)*L */
    printf("\n&a[2][1] - &a[0][0] = %d 个元素 = %d 字节\n",
           (int)(&a[2][1] - &a[0][0]),
           (int)((char *)&a[2][1] - (char *)a));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int m = 3, n = 4, i, j;
    int *a = (int *)malloc((size_t)m * n * sizeof(int));
    int *b = (int *)malloc((size_t)n * m * sizeof(int));
    if (a == NULL || b == NULL) {
        free(a); free(b);
        printf("malloc failed\n");
        return 1;
    }

    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            a[i * n + j] = i * n + j + 1;     /* 行优先填充 */

    printf("原矩阵 a（%dx%d，行优先存于一维数组）：\n", m, n);
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) printf("%4d", a[i * n + j]);
        printf("\n");
    }

    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            b[i * m + j] = a[j * n + i];      /* 转置：b[j][i] = a[i][j] */

    printf("\n转置矩阵 b（%dx%d，同样行优先）：\n", n, m);
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) printf("%4d", b[i * m + j]);
        printf("\n");
    }

    free(a);
    free(b);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define N 5

/* i,j 均为 1-based 位序，返回一维数组（0-based）下标 */
static int idx(int i, int j) {
    if (i >= j) { return i * (i - 1) / 2 + (j - 1); }
    return j * (j - 1) / 2 + (i - 1);
}

int main(void) {
    int size = N * (N + 1) / 2;
    int *sa = (int *)malloc((size_t)size * sizeof(int));
    int a[N][N];
    int i, j;

    if (sa == NULL) { printf("malloc failed\n"); return 1; }

    /* 先造一个下三角矩阵，再对称化 */
    for (i = 1; i <= N; i++)
        for (j = 1; j <= N; j++)
            a[i-1][j-1] = (i >= j) ? i * 10 + j : 0;
    for (i = 1; i <= N; i++)
        for (j = 1; j < i; j++)
            a[j-1][i-1] = a[i-1][j-1];

    /* 只把下三角（含对角线）压进一维数组 */
    for (i = 1; i <= N; i++)
        for (j = 1; j <= i; j++)
            sa[idx(i, j)] = a[i-1][j-1];

    printf("一维压缩数组（%d 个元素，原矩阵共 %d 个）：\n", size, N * N);
    for (i = 0; i < size; i++) printf("%d ", sa[i]);

    printf("\n\n由一维数组还原的对称矩阵：\n");
    for (i = 1; i <= N; i++) {
        for (j = 1; j <= N; j++) printf("%5d", sa[idx(i, j)]);
        printf("\n");
    }
    free(sa);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 128

typedef struct { int i, j; int e; } Triple;      /* 行、列（1-based）、值 */
typedef struct {
    Triple data[MAXSIZE];
    int mu, nu, tu;                              /* 行数、列数、非零元个数 */
} TSMatrix;

/* 快速转置：num[col] 记该列非零元个数，cpot[col] 记该列首元素的落位 */
void FastTransposeSMatrix(const TSMatrix *M, TSMatrix *T) {
    int num[MAXSIZE], cpot[MAXSIZE];
    int col, p, q;

    T->mu = M->nu; T->nu = M->mu; T->tu = M->tu;
    if (T->tu == 0) { return; }

    for (col = 1; col <= M->nu; col++) { num[col] = 0; }
    for (p = 0; p < M->tu; p++) { num[M->data[p].j]++; }
    cpot[1] = 0;
    for (col = 2; col <= M->nu; col++) { cpot[col] = cpot[col-1] + num[col-1]; }

    for (p = 0; p < M->tu; p++) {
        col = M->data[p].j;
        q = cpot[col];
        T->data[q].i = col;
        T->data[q].j = M->data[p].i;
        T->data[q].e = M->data[p].e;
        cpot[col]++;
    }
}

static void printM(const char *name, const TSMatrix *M) {
    int k;
    printf("%s：%d 行 %d 列，%d 个非零元\n", name, M->mu, M->nu, M->tu);
    for (k = 0; k < M->tu; k++) {
        printf("  (%d,%d) = %d\n", M->data[k].i, M->data[k].j, M->data[k].e);
    }
}

int main(void) {
    TSMatrix M, T;
    int rows[6] = {1, 2, 3, 4, 5, 6};
    int cols[6] = {2, 1, 3, 2, 4, 1};
    int vals[6] = {3, 5, 7, 9, 2, 8};
    int k;

    M.mu = 6; M.nu = 4; M.tu = 6;
    for (k = 0; k < M.tu; k++) {
        M.data[k].i = rows[k];
        M.data[k].j = cols[k];
        M.data[k].e = vals[k];
    }

    printM("原矩阵 M", &M);
    FastTransposeSMatrix(&M, &T);
    printf("\n");
    printM("转置矩阵 T", &T);
    return 0;
}
